import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Javascript Dialog","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/javascript-dialog.md","filePath":"documentation/field-types/javascript-dialog.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/javascript-dialog.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="javascript-dialog" tabindex="-1">Javascript Dialog <a class="header-anchor" href="#javascript-dialog" aria-label="Permalink to “Javascript Dialog”">​</a></h1><p>Run and hide native JavaScript dialogs (<code>alert</code>, <code>confirm</code>, <code>prompt</code>) on the page.</p><h2 id="alert-dialog" tabindex="-1">Alert Dialog <a class="header-anchor" href="#alert-dialog" aria-label="Permalink to “Alert Dialog”">​</a></h2><p>Triggers an <code>alert()</code> dialog on the page. You can set the message string directly in the field&#39;s default value or populate it dynamically from an Excel (.xlsx) column.</p><h2 id="confirm-dialog" tabindex="-1">Confirm Dialog <a class="header-anchor" href="#confirm-dialog" aria-label="Permalink to “Confirm Dialog”">​</a></h2><p>Triggers a <code>confirm()</code> dialog on the page. You can configure the confirmation prompt text in the field&#39;s default value or populate it from an Excel (.xlsx) column.</p><h2 id="prompt-dialog" tabindex="-1">Prompt Dialog <a class="header-anchor" href="#prompt-dialog" aria-label="Permalink to “Prompt Dialog”">​</a></h2><p>Triggers a <code>prompt()</code> dialog on the page. You can specify the prompt&#39;s default response value in the field&#39;s default value or map it from an Excel (.xlsx) column.</p><h3 id="prompt-string" tabindex="-1">Prompt String <a class="header-anchor" href="#prompt-string" aria-label="Permalink to “Prompt String”">​</a></h3><p>Specify the text message displayed inside the prompt dialog.</p><h2 id="hide-alert-dialog" tabindex="-1">Hide Alert Dialog <a class="header-anchor" href="#hide-alert-dialog" aria-label="Permalink to “Hide Alert Dialog”">​</a></h2><p>Automatically intercepts and dismisses <code>alert()</code> dialogs that appear on the page without blocking automation.</p><h2 id="get-alert-dialog-message" tabindex="-1">Get Alert Dialog Message <a class="header-anchor" href="#get-alert-dialog-message" aria-label="Permalink to “Get Alert Dialog Message”">​</a></h2><p>Captures the message text from incoming alert dialogs on the page.</p><h3 id="alert-dialog-message" tabindex="-1">Alert Dialog Message <a class="header-anchor" href="#alert-dialog-message" aria-label="Permalink to “Alert Dialog Message”">​</a></h3><p>The message string to match against incoming alerts can be defined in the field&#39;s default value or mapped from an Excel (.xlsx) column.</p><h3 id="wait-until-the-alert-message-is-received" tabindex="-1">Wait until the alert message is received <a class="header-anchor" href="#wait-until-the-alert-message-is-received" aria-label="Permalink to “Wait until the alert message is received”">​</a></h3><p>Keeps the automation waiting until an alert dialog with the expected text is intercepted.</p><h3 id="delete-the-message-after-getting-the-alert-message" tabindex="-1">Delete the message after getting the alert message <a class="header-anchor" href="#delete-the-message-after-getting-the-alert-message" aria-label="Permalink to “Delete the message after getting the alert message”">​</a></h3><p>Clears the captured alert message once processed so subsequent checks can receive new alerts.</p><h2 id="hide-confirm-dialog" tabindex="-1">Hide Confirm Dialog <a class="header-anchor" href="#hide-confirm-dialog" aria-label="Permalink to “Hide Confirm Dialog”">​</a></h2><p>To automatically click the <strong>OK</strong> button on a confirm dialog, provide the target confirm message in the field&#39;s default value. You can specify multiple messages separated by double commas (<code>,,</code>). If you leave the message empty, the extension will automatically click <strong>OK</strong> on any confirm dialog that appears.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/field-types/javascript-events.html">Javascript Events</a> — Programmatically trigger DOM events</li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a> — Advanced field configuration</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a> — Prepare Excel (.xlsx) templates</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> — Configure site-wide automation settings</li></ul>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};